        if left { selectedLeft = id } else { selectedRight = id }
        guard let a = selectedLeft, let b = selectedRight else { return }
        if a == b {
            matchedPairs.insert(a)
            matchingMessage = "Pair matched"
        } else {
            recordMistake()
            matchingMessage = "Those do not match. Try another pair."
        }
        selectedLeft = nil; selectedRight = nil
        if matchedPairs.count == question.pairs.count { feedback = true }
    }
    public mutating func submit() {
        guard canSubmit else { return }
